using Microsoft.EntityFrameworkCore;using RandomNumbersApi.Models;namespace RandomNumbersApi.Data{public class ApplicationDbContext : DbContext{public ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : base(options){}public DbSet<Item> Items => Set<Item>();protected override void OnModelCreating(ModelBuilder modelBuilder){base.OnModelCreating(modelBuilder);modelBuilder.Entity<Item>().Property(p => p.Name).IsRequired().HasMaxLength(200);}}}